  const effY_mm = Ly_mm - 2 * cover_mm;
  const nX = barCount({ length_mm: effY_mm, spacing_mm }); // bars running along X
  const nY = barCount({ length_mm: effX_mm, spacing_mm }); // bars running along Y
  const ded_mm = 2 * BBS_RULES.bendDeduction_d[90] * barDia_mm;
  const cutX_mm = effX_mm + 2 * hook_d * barDia_mm - ded_mm;
  const cutY_mm = effY_mm + 2 * hook_d * barDia_mm - ded_mm;
  const unit = kgPerM ?? barMassRounded_kgPerM(barDia_mm);
