/**
 * BBS table totals: per row total length = n × cut length; weight = total length × kg/m. T L1231-L1256 etc.
 * @param {{mark:string, dia_mm:number, n:number, cut_m:number, kgPerM?:number}[]} rows
 */
function bbsTotals(rows) {
  const out = rows.map((r) => {
    const kgPerM = r.kgPerM ?? barMassRounded_kgPerM(r.dia_mm);
    const total_m = r.n * r.cut_m;
    return { ...r, kgPerM, total_m, weight_kg: total_m * kgPerM };
  });
  return { rows: out, total_kg: out.reduce((a, r) => a + r.weight_kg, 0), ref: 'T L1231-L1545' };
}

