/** Degree of static indeterminacy D = reactions − equations (3 for a planar structure). T L2196-L2229. */
function degreeOfIndeterminacy({ reactions, equations = 3 }) {
  const D = reactions - equations;
  return { D, determinate: D === 0, ref: 'T L2213-L2229' };
}

/** Resultant of a UDL, P = w·L at L/2 of the loaded length. T L2590-L2601. */
function udlResultant({ w_kNm, length_m }) {
  return { P_kN: w_kNm * length_m, at_m: length_m / 2, ref: 'T L2590-L2601' };
}

/** Resultant of a triangular UVL, P = ½·w·L at L/3 from the heavier end (2L/3 from the zero end). T L2610-L2627. */
function uvlResultant({ wMax_kNm, length_m }) {
  return { P_kN: 0.5 * wMax_kNm * length_m, fromHeavyEnd_m: length_m / 3, fromZeroEnd_m: (2 * length_m) / 3, ref: 'T L2610-L2627' };
}

/** Normalise loads to resultants measured from support A. */
function resultants({ pointLoads = [], udls = [], uvls = [] }) {
  const R = [];
  for (const p of pointLoads) R.push({ P_kN: p.P_kN, x_m: p.a_m });
  for (const u of udls) R.push({ P_kN: u.w_kNm * (u.end_m - u.start_m), x_m: (u.start_m + u.end_m) / 2 });
  for (const v of uvls) {
    const L = v.end_m - v.start_m;
    const r = uvlResultant({ wMax_kNm: v.wMax_kNm, length_m: L });
    R.push({ P_kN: r.P_kN, x_m: v.heavyAt === 'start' ? v.start_m + r.fromHeavyEnd_m : v.start_m + r.fromZeroEnd_m });
  }
  return R;
}

/**
 * Reactions of a simply supported beam (pin at A, roller at B) under vertical point loads, UDLs and triangular UVLs:
 * ΣFx = 0 → Ax = 0; ΣMA = 0 → RB = ΣP·x / L; ΣFy = 0 → RA = ΣP − RB. T L2148-L2273, L3303-L3326.
 * Worked: T L2232-L2251 (100 kN at 5 m on 10 m), T L2252-L2273 (5 kN/m on 8 m), TR L1366-L1384 (120 kN at 2.5 m on 6 m).
 * @param {{span_m:number, pointLoads?:{P_kN:number,a_m:number}[], udls?:{w_kNm:number,start_m:number,end_m:number}[], uvls?:{wMax_kNm:number,start_m:number,end_m:number,heavyAt:'start'|'end'}[]}} p
 */
function simplySupportedReactions(p) {
  req(p, 'span_m');
  const R = resultants(p);
  const total_kN = R.reduce((a, r) => a + r.P_kN, 0);
  const momentA_kNm = R.reduce((a, r) => a + r.P_kN * r.x_m, 0);
  const RB_kN = momentA_kNm / p.span_m;
  const RA_kN = total_kN - RB_kN;
  const Ax_kN = 0;
  const steps = [
    step('Fx', 'ΣFx = 0', 'Ax = 0', Ax_kN, 'kN', 'T L2238'),
    step('Fy', 'ΣFy = 0', 'RA + RB = ΣP', total_kN, 'kN', 'T L2239-L2240'),
    step('MA', 'ΣMA = 0', 'RB × L = Σ(P × x)', momentA_kNm, 'kNm', 'T L2242'),
    step('RB', 'RB', 'RB = Σ(P × x) / L', RB_kN, 'kN', 'T L2246'),
    step('RA', 'RA', 'RA = ΣP − RB', RA_kN, 'kN', 'T L2251'),
  ];
  return { resultants: R, total_kN, momentA_kNm, RA_kN, RB_kN, Ax_kN, steps, ref: 'T L2148-L2273' };
}

