function loadCombinations({ Gk = 0, Qk = 0, Wk = 0 }) {
  const c1 = 1.4 * Gk + 1.6 * Qk;
  const c2 = 1.0 * Gk + 1.4 * Wk;
  const c3 = 1.2 * Gk + 1.2 * Qk + 1.2 * Wk;
  return {
    deadImposed: c1, deadWind: c2, deadImposedWind: c3,
    steps: [
      step('c1', 'Dead + imposed', '1.4Gk + 1.6Qk', c1, '', 'T L2642-L2644'),
      step('c2', 'Dead + wind', '1.0Gk + 1.4Wk', c2, '', 'T L2645-L2647'),
      step('c3', 'Dead + imposed + wind', '1.2Gk + 1.2Qk + 1.2Wk', c3, '', 'T L2648-L2650'),
    ],
    ref: 'T L2636-L2651',
  };
}

/** Factored load = working load × load factor. T L3282 (load factor method), L3304-L3307 (worked: 60 × 1.2 = 72 kN). */
function factoredLoad({ workingLoads, loadFactor }) {
  const working = workingLoads.reduce((a, b) => a + b, 0);
  return { working, loadFactor, design: working * loadFactor, ref: 'T L3282, L3304-L3307' };
}

/**
 * Slab load distribution to supporting beams by area (T L2711-L2722):
 * two-way: long beams take a trapezoid A1 = ½(B + b)·h1 with B = Ly, b = Ly − Lx, h1 = Lx/2;
 *          short beams take a triangle A2 = ½·B·h2 with B = Lx, h2 = Lx/2;
 * one-way: each long beam takes A = Ly × w with w = Lx/2.
 */
function slabTributaryAreas({ Lx_m, Ly_m }) {
  const b_m = Ly_m - Lx_m;
  const h1_m = Lx_m / 2;
  const A1_trapezoid_m2 = 0.5 * (Ly_m + b_m) * h1_m;
  const h2_m = Lx_m / 2;
  const A2_triangle_m2 = 0.5 * Lx_m * h2_m;
  const w_oneWay_m = Lx_m / 2;
  const A_oneWay_m2 = Ly_m * w_oneWay_m;
  return { b_m, h1_m, A1_trapezoid_m2, h2_m, A2_triangle_m2, w_oneWay_m, A_oneWay_m2, ref: 'T L2711-L2722' };
}

/** Column load from beams: half of each framing beam's load. T L2744-L2749. */
function columnLoadFromBeams({ beamLoads_kN }) {
  const shares_kN = beamLoads_kN.map((w) => w / 2);
  return { shares_kN, N_kN: shares_kN.reduce((a, b) => a + b, 0), ref: 'T L2744-L2749' };
}

/**
 * One-way slab load to its two beams plus beam self-weight. Trainer worked answer TR L1385-L1404
 * (9 m × 3 m, 20 kN/m², beams 0.2 × 0.2 m, 24 kN/m³ → 278.64 kN per beam).
 */
function oneWaySlabToBeams({ span_m, width_m, w_kNm2, beamB_m, beamH_m, unitWeight_kNm3 }) {
  const area_m2 = span_m * width_m;
  const slab_kN = w_kNm2 * area_m2;
  const perBeam_kN = slab_kN / 2;
  const beamVolume_m3 = beamB_m * beamH_m * span_m;
  const beamSelf_kN = beamVolume_m3 * unitWeight_kNm3;
  return { area_m2, slab_kN, perBeam_kN, beamVolume_m3, beamSelf_kN, totalPerBeam_kN: perBeam_kN + beamSelf_kN, ref: 'TR L1385-L1404' };
}

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.1 - internal forces, SFD/BMD (T L3154-L3231)
// ---------------------------------------------------------------------------------------------------------------

/** Maximum moments, T L3204 and the table T L3715-L3730. Simply supported UDL: M = wL²/8. */
const momentSimpleUdl_kNm = ({ w_kNm, L_m }) => (w_kNm * L_m ** 2) / 8;
/** Simply supported, point load at centre: M = PL/4 (the manual prints "M = PL", T L3723 - errata). */
const momentSimplePointCentre_kNm = ({ P_kN, L_m }) => (P_kN * L_m) / 4;
/** Cantilever, point load at free end: M = PL (row left blank in the manual, T L3725-L3727 - errata). */
const momentCantileverPoint_kNm = ({ P_kN, L_m }) => P_kN * L_m;
/** Cantilever, full UDL: M = wL²/2. T L3728-L3730. */
const momentCantileverUdl_kNm = ({ w_kNm, L_m }) => (w_kNm * L_m ** 2) / 2;

/**
 * Shear force and bending moment along a simply supported beam (T L3187-L3231): V(x) = RA − Σ loads left of x;
 * M(x) = RA·x − Σ moments of loads left of x. Returns sampled diagrams, Vmax, Mmax and its position (where V = 0).
 */
function simplySupportedDiagrams({ span_m, pointLoads = [], udls = [], n = 201 }) {
  const { RA_kN, RB_kN } = simplySupportedReactions({ span_m, pointLoads, udls });
  const x_m = [];
  const V_kN = [];
  const M_kNm = [];
  const at = (x, side) => {
    let V = RA_kN;
    let M = RA_kN * x;
    for (const p of pointLoads) {
      if (p.a_m < x || (side === 'right' && p.a_m === x)) { V -= p.P_kN; M -= p.P_kN * (x - p.a_m); }
    }
    for (const u of udls) {
      const l = Math.max(0, Math.min(x, u.end_m) - u.start_m);
      if (l > 0) { V -= u.w_kNm * l; M -= u.w_kNm * l * (x - (u.start_m + l / 2)); }
    }
    return { V, M };
  };
  const xs = new Set();
  for (let i = 0; i < n; i++) xs.add((span_m * i) / (n - 1));
  for (const p of pointLoads) xs.add(p.a_m);
  for (const x of [...xs].sort((a, b) => a - b)) {
    const l = at(x, 'left');
    x_m.push(x); V_kN.push(l.V); M_kNm.push(l.M);
    if (pointLoads.some((p) => p.a_m === x)) { const r = at(x, 'right'); x_m.push(x); V_kN.push(r.V); M_kNm.push(r.M); }
  }
  let iMax = 0;
  for (let i = 1; i < M_kNm.length; i++) if (Math.abs(M_kNm[i]) > Math.abs(M_kNm[iMax])) iMax = i;
  const Vmax_kN = Math.max(...V_kN.map(Math.abs));
  return { RA_kN, RB_kN, x_m, V_kN, M_kNm, Vmax_kN, Mmax_kNm: M_kNm[iMax], xMmax_m: x_m[iMax], ref: 'T L3187-L3231' };
}

/** Average shear stress τ = V / A. T L3179-L3181. */
const averageShearStress_MPa = ({ V_kN, A_mm2 }) => (V_kN * 1e3) / A_mm2;

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.2 - methods of design (T L3248-L3355; worked answer TR L1604-L1647)
// ---------------------------------------------------------------------------------------------------------------

/** Permissible stress = yield (or ultimate) stress / factor of safety. T L3264-L3270. */
const permissibleStress_MPa = ({ strength_MPa, factorOfSafety }) => strength_MPa / factorOfSafety;

/**
 * The three design methods on one simply supported rectangular beam, as the trainer's answer to Task 36
 * (TR L1604-L1647): I = bh³/12, Z = I/(h/2), M = wL²/8, σ = M/Z; factored w = 1.5w.
 */
function designMethodsComparison({ w_kNm, span_m, b_mm, h_mm, permissible_MPa, loadFactor, concreteStrength_MPa }) {
  const I_mm4 = (b_mm * h_mm ** 3) / 12;
  const Z_mm3 = I_mm4 / (h_mm / 2);
  const Ms_kNm = momentSimpleUdl_kNm({ w_kNm, L_m: span_m });
  const sigmaS_MPa = (Ms_kNm * 1e6) / Z_mm3;
  const wu_kNm = loadFactor * w_kNm;
  const Mu_kNm = momentSimpleUdl_kNm({ w_kNm: wu_kNm, L_m: span_m });
  const sigmaU_MPa = (Mu_kNm * 1e6) / Z_mm3;
  return {
    I_mm4, Z_mm3, Ms_kNm, sigmaS_MPa, wu_kNm, Mu_kNm, sigmaU_MPa,
    checks: [
      check('permissible', 'σ (service) ≤ permissible stress', sigmaS_MPa <= permissible_MPa, 'TR L1621-L1626'),
      check('loadFactor', 'σ (factored) ≤ concrete strength', sigmaU_MPa <= concreteStrength_MPa, 'TR L1633-L1637'),
    ],
    ref: 'T L3318-L3346, TR L1604-L1647',
  };
}

/** Column under axial service load, permissible stress method (T L3350-L3355): σ = P/A ≤ σperm; Amin = P/σperm. */
function axialPermissibleCheck({ P_kN, b_mm, h_mm, permissible_MPa }) {
  const A_mm2 = b_mm * h_mm;
  const sigma_MPa = (P_kN * 1e3) / A_mm2;
  return { A_mm2, sigma_MPa, safe: sigma_MPa <= permissible_MPa, Amin_mm2: (P_kN * 1e3) / permissible_MPa, ref: 'T L3350-L3355' };
}

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.3 - serviceability: cover, spacing, steel area limits, deflection (T L3357-L3591)
// ---------------------------------------------------------------------------------------------------------------

/** Typical nominal cover ranges (mm). T L3379-L3405 (and BBS basics T L1136-L1138). */
const NOMINAL_COVER_mm = Object.freeze({
  slabInternal: [15, 20], slabExternal: [25, 30], beamInternal: [25, 30], beamExternal: [30, 40],
  columnInternal: [30, 40], columnExternal: [40, 50], footing: [50, 75],
});

/**
 * Spacing rules as tabulated in the manual.
 * Beams (T L3526-L3540): clear horizontal spacing ≥ bar diameter and ≥ max aggregate + 5 mm; between layers ≥ 15 mm;
 * links ≥ about 80 mm. General minimum (T L3551): ≥ max(bar diameter, 1.33 × max aggregate).
 * Slabs (T L3543-L3549): main bars ≤ min(3d, 300 mm) (table); distribution ≤ min(5d, 450 mm); clear spacing ≥ 75 mm
 * (100 preferred); text: one-way ≤ min(3h, 450), two-way ≤ min(2h, 300) (T L3543).
 */
function spacingRules({ barDia_mm, maxAggregate_mm, slabD_mm, slabThickness_mm }) {
  const beamMinClear_mm = Math.max(barDia_mm, maxAggregate_mm + 5);
  const generalMinClear_mm = Math.max(barDia_mm, 1.33 * maxAggregate_mm);
  const out = { beamMinClear_mm, beamMinBetweenLayers_mm: 15, linkMinSpacing_mm: 80, generalMinClear_mm, ref: 'T L3524-L3551' };
  if (slabD_mm !== undefined) {
    out.slabMainMax_mm = Math.min(3 * slabD_mm, 300);
    out.slabDistributionMax_mm = Math.min(5 * slabD_mm, 450);
  }
  // T L3543 (text): slab minimum clear spacing 75 mm (100 mm preferred); max spacing one-way min(3h, 450) - differs
  // from the table's min(3d, 300), E-30 / OQ-08; two-way min(2h, 300).
  out.slabMinClear_mm = 75;
  out.slabPreferredClear_mm = 100;
  if (slabThickness_mm !== undefined) {
    out.slabOneWayMaxText_mm = Math.min(3 * slabThickness_mm, 450);
    out.slabTwoWayMax_mm = Math.min(2 * slabThickness_mm, 300);
  }
  return out;
}

/** Maximum tension steel in beams: about 4 % of the gross section. T L3563. */
const maxSteelArea_mm2 = ({ b_mm, h_mm }) => 0.04 * b_mm * h_mm;

/** δmax = 5wL⁴/(384EI), simply supported UDL (w = total load per length). T L3464-L3471 (equation in .docx). */
const deflectionSimpleUdl_mm = ({ w_kNm, L_m, E_MPa, I_mm4 }) => (5 * w_kNm * (L_m * 1e3) ** 4) / (384 * E_MPa * I_mm4);
/** δmax = PL³/(48EI), simply supported, point load at centre. T L3472-L3475. */
const deflectionSimplePointCentre_mm = ({ P_kN, L_m, E_MPa, I_mm4 }) => (P_kN * 1e3 * (L_m * 1e3) ** 3) / (48 * E_MPa * I_mm4);
/** δmax = PL³/(3EI), cantilever, point load at free end. T L3476-L3479. */
const deflectionCantileverPoint_mm = ({ P_kN, L_m, E_MPa, I_mm4 }) => (P_kN * 1e3 * (L_m * 1e3) ** 3) / (3 * E_MPa * I_mm4);

/** Effective span of a simply supported member: min(centre-to-centre, clear span + d). T L3490-L3493. */
function effectiveSpan({ clearSpan_m, d_m, centres_m }) {
  const clearPlusD_m = clearSpan_m + d_m;
  const Leff_m = centres_m === undefined ? clearPlusD_m : Math.min(centres_m, clearPlusD_m);
  return { clearPlusD_m, centres_m, Leff_m, ref: 'T L3490-L3493' };
}

/** Basic span/effective depth ratios, rectangular sections (BS 8110 Table 3.9; not in the manual, OQ-10). */
const BASIC_SPAN_DEPTH = Object.freeze({ cantilever: 7, simple: 20, continuous: 26 });

/**
 * Modification factor for tension steel (BS 8110 Table 3.10, eq. 7; not in the manual, OQ-10):
 * fs = 2fy·As,req / (3As,prov); MF = 0.55 + (477 − fs) / (120(0.9 + M/bd²)) ≤ 2.0.
 */
function deflectionModificationFactor({ M_kNm, b_mm, d_mm, fy_MPa, As_req_mm2, As_prov_mm2 }) {
  const fs_MPa = (2 * fy_MPa * As_req_mm2) / (3 * As_prov_mm2);
  const Mbd2 = (M_kNm * 1e6) / (b_mm * d_mm * d_mm);
  const raw = 0.55 + (477 - fs_MPa) / (120 * (0.9 + Mbd2));
  return { fs_MPa, Mbd2, raw, MF: Math.min(raw, 2), ref: `${BSREF} Table 3.10 eq. 7` };
}

/**
 * Span/depth deflection control (T L3674, L4015-L4018, L4169-L4175): d ≥ span / (L/d basic × m.f.) and
 * L/d actual < L/d allowable. The manual names the basic ratio and the modification factor but gives no numbers
 * (OQ-10): if not passed, the basic ratio comes from BASIC_SPAN_DEPTH[support] and the factor from
 * deflectionModificationFactor (needs M_kNm, b_mm, fy_MPa, As_req_mm2, As_prov_mm2).
 */
function spanDepthCheck({ span_mm, d_mm, basicRatio, modificationFactor, support = 'simple', M_kNm, b_mm, fy_MPa, As_req_mm2, As_prov_mm2 }) {
  const basic = basicRatio ?? BASIC_SPAN_DEPTH[support];
  if (basic === undefined) throw new TypeError(`calc: unknown support "${support}"`);
  let mf = modificationFactor;
  let mfInfo = null;
  if (mf === undefined) {
    req({ M_kNm, b_mm, fy_MPa, As_req_mm2, As_prov_mm2 }, 'M_kNm', 'b_mm', 'fy_MPa', 'As_req_mm2', 'As_prov_mm2');
    mfInfo = deflectionModificationFactor({ M_kNm, b_mm, d_mm, fy_MPa, As_req_mm2, As_prov_mm2 });
    mf = mfInfo.MF;
  }
  const allowable = basic * mf;
  const actual = span_mm / d_mm;
  const dMin_mm = span_mm / allowable;
  const bsNote = 'The manual names the basic ratio and the modification factor but gives no values. BS 8110 Table 3.9 and eq. 7 are used.';
  const steps = [];
  if (basicRatio === undefined) steps.push(step('Lbasic', 'Basic span/depth ratio', `L/d basic (${support})`, basic, '', `${BSREF} Table 3.9`, CHIP.BS, bsNote));
  if (mfInfo) {
    steps.push(step('fs', 'Steel service stress', 'fs = 2fy·As,req / (3As,prov)', mfInfo.fs_MPa, 'N/mm²', `${BSREF} Table 3.10`, CHIP.BS, bsNote));
    steps.push(step('MF', 'Modification factor', 'MF = 0.55 + (477 − fs) / (120(0.9 + M/bd²)) ≤ 2', mf, '', `${BSREF} Table 3.10 eq. 7`, CHIP.BS, bsNote));
  }
  steps.push(
    step('dmin', 'Effective depth needed', 'd = span / (L/d basic × m.f.)', dMin_mm, 'mm', 'T L3674, L4015'),
    step('Ld', 'Actual span/depth', 'L/d actual = L / d', actual, '', 'T L4171'),
    step('Lallow', 'Allowable span/depth', 'L/d allowable = L/d basic × m.f.', allowable, '', 'T L4171'),
  );
  return {
    basicRatio: basic, modificationFactor: mf, mf: mfInfo, allowable, actual, dMin_mm, utilisation: actual / allowable,
    steps,
    checks: [check('deflection', 'L/d actual < L/d allowable', actual < allowable, 'T L4171')],
    ref: 'T L3674, L4015-L4018, L4169-L4175',
  };
}

/**
 * Minimum tension steel (BS 8110 Table 3.25; not in the manual, OQ-12): 0.13 % b·h for high yield steel
 * (fy ≥ 460), 0.24 % b·h for mild steel (fy 250).
 */
function minSteelArea_mm2({ b_mm, h_mm, fy_MPa }) {
  const ratio = fy_MPa >= 400 ? 0.0013 : 0.0024;
  return ratio * b_mm * h_mm;
}

/** Modulus of elasticity of concrete, Ec = 20 + 0.2fcu kN/mm² (BS 8110-2 eq. 17; not in the manual, OQ-17). In N/mm². */
const concreteModulus_MPa = ({ fcu_MPa }) => (20 + 0.2 * fcu_MPa) * 1000;

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.4 - beam (T L3633-L3896)
// ---------------------------------------------------------------------------------------------------------------

/** Limits used by the manual's flexure procedure. T L3740, L4039-L4040 (k' = 0.156), L3747-L3758 (z/d). */
const FLEXURE_LIMITS = Object.freeze({ kPrime: 0.156, zMinOverD: 0.775, zMaxOverD: 0.95 });

/**
 * Beam design loads (T L3705-L3714): Gk = b·D·γ + other dead (kN/m); Qk = q·bt + other imposed (kN/m);
 * w = 1.4Gk + 1.6Qk.
 */
function beamDesignLoad({ b_m = 0, D_m = 0, unitWeight_kNm3 = 0, otherGk_kNm = 0, q_kNm2 = 0, tributary_m = 0, otherQk_kNm = 0 }) {
  const selfWeight_kNm = b_m * D_m * unitWeight_kNm3;
  const Gk_kNm = selfWeight_kNm + otherGk_kNm;
  const Qk_kNm = q_kNm2 * tributary_m + otherQk_kNm;
  const w_kNm = 1.4 * Gk_kNm + 1.6 * Qk_kNm;
  return {
    selfWeight_kNm, Gk_kNm, Qk_kNm, w_kNm,
    steps: [
      step('sw', 'Self-weight', 'b × D × γ', selfWeight_kNm, 'kN/m', 'T L3707-L3710'),
      step('Gk', 'Dead load Gk', 'self-weight + other dead', Gk_kNm, 'kN/m', 'T L3707'),
      step('Qk', 'Imposed load Qk', 'q × bt', Qk_kNm, 'kN/m', 'T L3711-L3713'),
      step('w', 'Ultimate load', 'w = 1.4Gk + 1.6Qk', w_kNm, 'kN/m', 'T L3714'),
    ],
    ref: 'T L3705-L3714',
  };
}

/**
 * Neutral axis depth from the manual's section-analysis formulas, T L3676-L3686 and L3759-L3764:
 * x = 0.87·fy·As / (0.36·fck·b), z = d(1 − 0.42k) with k = x/d, and As = M / (0.87·fy·z). Eliminating As gives
 * M = 0.36·fck·b·x·(d − 0.42x), solved here for the smaller root x. Returns null when M exceeds the largest moment the
 * expression can give (0.36·fck·b·d²/(4 × 0.42)).
 */
function neutralAxisFromMoment({ M_kNm, b_mm, d_mm, fck_MPa }) {
  const a = 0.36 * fck_MPa * b_mm * 0.42;
  const bq = -0.36 * fck_MPa * b_mm * d_mm;
  const c = M_kNm * 1e6;
  const disc = bq * bq - 4 * a * c;
  if (disc < 0) return null;
  return (-bq - Math.sqrt(disc)) / (2 * a);
}

/**
 * Flexural design of a rectangular section, steps exactly as the manual's beam procedure (T L3732-L3888):
 * neutral axis x (T L3676-L3686), k = x/d (T L3732-L3738), k ≤ k' = 0.156 (T L3739-L3740), z/d (T L3741-L3746),
 * 0.775d ≤ z ≤ 0.95d (T L3747-L3758), z = d(1 − 0.42k) (T L3759-L3761), As = M/(0.87·fy·z) (T L3762-L3768).
 * NOTE (errata/open question): k' = 0.156 is the BS 8110 limit for K = M/(b·d²·fcu), not for x/d; the manual mixes
 * the two. The check is reported as the manual states it, and the lab must not hide the z-limits check.
 * Pass `leverArm: 'elastic'` for the slab variant z = d(1 − k/3) (T L4045-L4048), or `zOverD` to impose a given
 * lever-arm ratio (summative T L5127, "Take z/d = 0.95").
 */
function flexureDesignManual({ M_kNm, b_mm, d_mm, fck_MPa: fckIn, fcu_MPa, fy_MPa, leverArm = 'beam', zOverD }) {
  // The manual's x formula uses fck (T L3684); tasks give fcu (e.g. T L3907). When only fcu is given it is used as fck
  // and the step says so (E-25 / OQ-01).
  const fck_MPa = fckIn ?? fcu_MPa;
  const fckNote = fckIn === undefined && fcu_MPa !== undefined ? ' (fck taken = fcu)' : '';
  req({ M_kNm, b_mm, d_mm, fck_MPa, fy_MPa }, 'M_kNm', 'b_mm', 'd_mm', 'fck_MPa', 'fy_MPa');
  const x_mm = neutralAxisFromMoment({ M_kNm, b_mm, d_mm, fck_MPa });
  const steps = [];
  const checks = [];
  if (x_mm === null) {
    checks.push(check('section', 'Section can develop M (neutral-axis equation has a solution)', false, 'T L3676-L3686'));
    return { x_mm: null, k: null, z_mm: null, As_req_mm2: null, steps, checks, ok: false, ref: 'T L3732-L3888' };
  }
  const k = x_mm / d_mm;
  let z_mm;
  let zFormula;
  if (zOverD !== undefined) { z_mm = zOverD * d_mm; zFormula = 'z = (z/d) × d'; }
  else if (leverArm === 'elastic') { z_mm = d_mm * (1 - k / 3); zFormula = 'z = d(1 − k/3)'; }
  else { z_mm = d_mm * (1 - 0.42 * k); zFormula = 'z = d(1 − 0.42k)'; }
  const zRatio = z_mm / d_mm;
  const As_req_mm2 = (M_kNm * 1e6) / (0.87 * fy_MPa * z_mm);
  steps.push(
    step('x', 'Neutral axis depth', `x = 0.87·fy·As / (0.36·fck·b)${fckNote}${leverArm === 'elastic' ? ' [slab: the manual names the transformed-section method but gives no formula; beam formula used, OQ-01]' : ''}`, x_mm, 'mm', 'T L3676-L3686'),
    step('k', 'Neutral axis ratio', 'k = x / d', k, '', 'T L3735-L3738'),
    step('z', 'Lever arm', zFormula, z_mm, 'mm', leverArm === 'elastic' ? 'T L4046' : 'T L3761'),
    step('zd', 'Lever arm ratio', 'z / d', zRatio, '', 'T L3741-L3746'),
    step('As', 'Tension steel required', 'As = M / (0.87·fy·z)', As_req_mm2, 'mm²', 'T L3762-L3768'),
  );
  checks.push(
    check('k', "k ≤ k' = 0.156", k <= FLEXURE_LIMITS.kPrime, 'T L3739-L3740'),
    check('zmin', 'z ≥ 0.775d', zRatio >= FLEXURE_LIMITS.zMinOverD - 1e-9, 'T L3750-L3753'),
    check('zmax', 'z ≤ 0.95d', zRatio <= FLEXURE_LIMITS.zMaxOverD + 1e-9, 'T L3754-L3757'),
  );
  return { method: 'manual', x_mm, k, z_mm, zRatio, As_req_mm2, steps, checks, ok: checks.every((c) => c.ok), ref: 'T L3732-L3888' };
}

/** BS 8110 lever arm z = d[0.5 + √(0.25 − K/0.9)] (eq. in 3.4.4.4), uncapped. */
const leverArmBS = (K, d_mm) => d_mm * (0.5 + Math.sqrt(Math.max(0, 0.25 - K / 0.9)));

const FLEX_NOTE_K = 'The manual writes k = x/d and checks it against 0.156. That limit belongs to the BS 8110 K = M/(b d² fcu), which the lab uses.';
const FLEX_NOTE_Z = 'The manual prints z = d(1 − 0.42k) for beams and z = d(1 − k/3) for slabs. The lab uses the BS 8110 lever arm, capped at 0.95d.';

/**
 * Flexural design of a rectangular section (OQ-01, OQ-02 ruling; DIGEST rule 2). Default `method: 'bs'`:
 * K = M/(b·d²·fcu), K' = 0.156; z = d[0.5 + √(0.25 − K/0.9)] capped at 0.95d (the cap is not a failure);
 * As = M/(0.87·fy·z) (the manual's T L3762-L3768); x = (d − z)/0.45 and the manual's k = x/d shown as a manual note.
 * K > K': the singly reinforced section cannot carry M (concrete crushes at the top): check 'k' fails,
 * compressionSteelNeeded = true, As is reported with z at K'. `zOverD` imposes a lever arm ratio given by a task
 * (summative T L5127, "Take z/d = 0.95"). `method: 'manual'` gives the manual's printed route (flexureDesignManual).
 * fcu is used for K; when only fck is passed it is used as fcu (note on the K step).
 */
function flexureDesign(p) {
  if (p.method === 'manual') return flexureDesignManual(p);
  const { M_kNm, b_mm, d_mm, fy_MPa, zOverD } = p;
  const fcu_MPa = p.fcu_MPa ?? p.fck_MPa;
  const fcuNote = p.fcu_MPa === undefined && p.fck_MPa !== undefined ? ' (fcu taken = fck)' : '';
  req({ M_kNm, b_mm, d_mm, fcu_MPa, fy_MPa }, 'M_kNm', 'b_mm', 'd_mm', 'fcu_MPa', 'fy_MPa');
  const Kprime = FLEXURE_LIMITS.kPrime;
  const K = (M_kNm * 1e6) / (b_mm * d_mm * d_mm * fcu_MPa);
  const compressionSteelNeeded = K > Kprime;
  let z_mm;
  let zRaw_mm;
  let zCapped = false;
  const steps = [step('K', 'Moment factor', `K = M / (b·d²·fcu)${fcuNote}`, K, '', 'T L3732-L3740', CHIP.NOTE, FLEX_NOTE_K)];
  if (zOverD !== undefined) {
    zRaw_mm = zOverD * d_mm;
    z_mm = zRaw_mm;
    steps.push(step('z', 'Lever arm', 'z = (z/d) × d (given)', z_mm, 'mm', 'T L5127'));
  } else {
    zRaw_mm = leverArmBS(Math.min(K, Kprime), d_mm);
    zCapped = zRaw_mm > FLEXURE_LIMITS.zMaxOverD * d_mm;
    z_mm = Math.min(zRaw_mm, FLEXURE_LIMITS.zMaxOverD * d_mm);
    steps.push(step('z', 'Lever arm', `z = d[0.5 + √(0.25 − K/0.9)] ≤ 0.95d${zCapped ? ' (capped at 0.95d)' : ''}${compressionSteelNeeded ? " (at K')" : ''}`,
      z_mm, 'mm', 'T L3741-L3761', CHIP.NOTE, FLEX_NOTE_Z));
  }
  const zRatio = z_mm / d_mm;
  const x_mm = (d_mm - z_mm) / 0.45;
  const k = x_mm / d_mm;
  const As_req_mm2 = (M_kNm * 1e6) / (0.87 * fy_MPa * z_mm);
  steps.push(
    step('zd', 'Lever arm ratio', 'z / d', zRatio, '', 'T L3741-L3746'),
    step('x', 'Neutral axis depth', 'x = (d − z) / 0.45', x_mm, 'mm', 'T L3676-L3686', CHIP.NOTE, 'The manual finds x from 0.87fy·As/(0.36fck·b). Here x follows from the BS 8110 lever arm.'),
    step('k', 'Neutral axis ratio', 'k = x / d', k, '', 'T L3735-L3738', CHIP.NOTE, "The manual's k = x/d, shown for reference only."),
    step('As', 'Tension steel required', 'As = M / (0.87·fy·z)', As_req_mm2, 'mm²', 'T L3762-L3768'),
  );
  const checks = [
    check('k', "K ≤ K' = 0.156 (else the top concrete crushes: deepen the section)", !compressionSteelNeeded, 'T L3739-L3740', CHIP.NOTE, FLEX_NOTE_K),
    check('zmin', 'z ≥ 0.775d', zRatio >= FLEXURE_LIMITS.zMinOverD - 1e-9, 'T L3750-L3753'),
    check('zmax', 'z ≤ 0.95d (capped, not a failure)', zRatio <= FLEXURE_LIMITS.zMaxOverD + 1e-9 || zOverD !== undefined, 'T L3754-L3757', CHIP.NOTE, 'The cap at 0.95d is applied, so a lightly loaded section does not fail this check.'),
  ];
  return {
    method: 'bs', K, Kprime, x_mm, k, z_mm, zRaw_mm, zRatio, zCapped, As_req_mm2, compressionSteelNeeded,
    utilisation: K / Kprime, steps, checks, ok: checks.every((c) => c.ok), ref: `T L3732-L3888, ${BSREF} 3.4.4.4`,
  };
}

/**
 * Choose the number of bars of a given diameter so that As,prov ≥ As,req ("slightly greater"). T L3769-L3771,
 * L3883-L3888.
 */
function selectBars({ As_req_mm2, barDia_mm }) {
  const Abar_mm2 = barArea_mm2(barDia_mm);
  const n = Math.max(1, Math.ceil(As_req_mm2 / Abar_mm2 - 1e-9));
  return { Abar_mm2, n, As_prov_mm2: n * Abar_mm2, ok: n * Abar_mm2 >= As_req_mm2, label: `${n}Y${barDia_mm}`, ref: 'T L3769-L3771, L3883-L3888' };
}

/**
 * Concrete shear capacity vc (OQ-09 ruling; the manual prints the formula without limits, γm or the fcu factor,
 * T L4906-L4915, image139): vc = 0.79·(100As/bd)^⅓·(400/d)^¼·(fcu/25)^⅓ / γm with γm = 1.25, 100As/bd ≤ 3,
 * fcu ≤ 40 in the fcu factor (factor 1 when fcu is not passed), and (400/d)^¼ ≥ 1 for members with links
 * (`withLinks`, default true) or ≥ 0.67 for members without links such as pad footings (BS 8110 Table 3.8 notes).
 */
function concreteShearCapacity({ As_mm2, b_mm, d_mm, gammaM = 1.25, fcu_MPa, withLinks = true }) {
  const rho100 = (100 * As_mm2) / (b_mm * d_mm);
  const rho100Used = Math.min(rho100, 3);
  const depthFactorRaw = (400 / d_mm) ** 0.25;
  const depthFactorMin = withLinks ? 1 : 0.67;
  const depthFactor = Math.max(depthFactorRaw, depthFactorMin);
  const fcuFactor = fcu_MPa === undefined ? 1 : (Math.min(fcu_MPa, 40) / 25) ** (1 / 3);
  const vc_MPa = (0.79 * rho100Used ** (1 / 3) * depthFactor * fcuFactor) / gammaM;
  return {
    rho100, rho100Used, depthFactorRaw, depthFactorMin, depthFactor, fcuFactor, gammaM, vc_MPa,
    step: step('vc', 'Concrete shear capacity', 'vc = 0.79(100As/bd)^⅓ (400/d)^¼ (fcu/25)^⅓ / γm, γm = 1.25', vc_MPa, 'N/mm²', 'T L4906-L4915 (image139)',
      CHIP.NOTE, 'The manual prints the formula without γm, the factor (fcu/25)^⅓ and the limits. BS 8110 Table 3.8 values are used.'),
    ref: `T L4906-L4915 (image139), ${BSREF} Table 3.8`,
  };
}

/**
 * Beam shear and links (OQ-13 ruling, BS 8110 3.4.5; the manual gives no beam shear design):
 * v = V/(b·d) ≤ min(0.8√fcu, 5); v < 0.5vc: minimum links; 0.5vc ≤ v < vc + 0.4: Asv/sv ≥ 0.4b/(0.87fyv);
 * above: Asv/sv ≥ b(v − vc)/(0.87fyv); sv ≤ 0.75d. With links given: link capacity vs = 0.87fyv·Asv/(b·sv),
 * capacity v,cap = vc + vs. Diagonal shear cracks appear where v > vc + link capacity: for a UDL (w_kNm, span_m)
 * that is within crackFromSupport_m of each support (0 = no crack).
 */
function beamShearDesign({ V_kN, b_mm, d_mm, fcu_MPa, As_mm2, fyv_MPa, linkDia_mm, linkSpacing_mm, linkLegs = 2, w_kNm, span_m, gammaM = 1.25 }) {
  req({ V_kN, b_mm, d_mm, fcu_MPa, As_mm2, fyv_MPa }, 'V_kN', 'b_mm', 'd_mm', 'fcu_MPa', 'As_mm2', 'fyv_MPa');
  const ref = `${BSREF} 3.4.5 (not in the manual)`;
  const note = 'The manual gives no beam shear design. BS 8110 clause 3.4.5 is used.';
  const v_MPa = (V_kN * 1e3) / (b_mm * d_mm);
  const vmax_MPa = Math.min(0.8 * Math.sqrt(fcu_MPa), 5);
  const vc = concreteShearCapacity({ As_mm2, b_mm, d_mm, gammaM, fcu_MPa, withLinks: true });
  const vc_MPa = vc.vc_MPa;
  const zone = v_MPa < 0.5 * vc_MPa ? 'nominal' : v_MPa < vc_MPa + 0.4 ? 'minimum' : 'design';
  const AsvSv_min = (0.4 * b_mm) / (0.87 * fyv_MPa);
  const AsvSv_req = zone === 'design' ? (b_mm * (v_MPa - vc_MPa)) / (0.87 * fyv_MPa) : AsvSv_min;
  const svMax_mm = 0.75 * d_mm;
  const steps = [
    step('v', 'Shear stress', 'v = V / (b·d)', v_MPa, 'N/mm²', ref, CHIP.BS, note),
    step('vmax', 'Maximum shear stress', 'v max = min(0.8√fcu, 5)', vmax_MPa, 'N/mm²', ref, CHIP.BS, note),
    { ...vc.step, ref: `${BSREF} Table 3.8`, chip: CHIP.BS, note },
    step('AsvSv', zone === 'design' ? 'Links needed' : 'Minimum links', zone === 'design' ? 'Asv/sv = b(v − vc) / (0.87fyv)' : 'Asv/sv = 0.4b / (0.87fyv)', AsvSv_req, 'mm²/mm', `${BSREF} Table 3.7`, CHIP.BS, note),
    step('svmax', 'Maximum link spacing', 'sv ≤ 0.75d', svMax_mm, 'mm', `${BSREF} 3.4.5.5`, CHIP.BS, note),
  ];
  const checks = [check('vmax', 'v ≤ min(0.8√fcu, 5 N/mm²) (else the web crushes)', v_MPa <= vmax_MPa, ref, CHIP.BS, note)];
  let links = null;
  let vCap_MPa = vc_MPa;
  if (linkDia_mm !== undefined && linkSpacing_mm !== undefined) {
    const Asv_mm2 = linkLegs * barArea_mm2(linkDia_mm);
    const AsvSv_prov = Asv_mm2 / linkSpacing_mm;
    const vs_MPa = (0.87 * fyv_MPa * AsvSv_prov) / b_mm;
    vCap_MPa = vc_MPa + vs_MPa;
    links = { Asv_mm2, AsvSv_prov, vs_MPa, vCap_MPa, label: `R${linkDia_mm} at ${linkSpacing_mm}` };
    steps.push(
      step('Asvprov', 'Links provided', `Asv/sv = ${linkLegs} legs × πφ²/4 / sv`, AsvSv_prov, 'mm²/mm', ref, CHIP.BS, note),
      step('vcap', 'Shear capacity with links', 'v cap = vc + 0.87fyv·Asv / (b·sv)', vCap_MPa, 'N/mm²', ref, CHIP.BS, note),
    );
    checks.push(
      check('links', 'Asv/sv provided ≥ required', AsvSv_prov >= AsvSv_req - 1e-12, `${BSREF} Table 3.7`, CHIP.BS, note),
      check('sv', 'Link spacing ≤ 0.75d', linkSpacing_mm <= svMax_mm + 1e-9, `${BSREF} 3.4.5.5`, CHIP.BS, note),
      check('vcap', 'v ≤ vc + link capacity (else diagonal shear cracks near the supports)', v_MPa <= vCap_MPa + 1e-12, ref, CHIP.BS, note),
    );
  }
  let crackFromSupport_m = null;
  if (w_kNm !== undefined && span_m !== undefined && w_kNm > 0) {
    const Vcap_kN = (vCap_MPa * b_mm * d_mm) / 1e3;
    crackFromSupport_m = Math.max(0, Math.min(span_m / 2, span_m / 2 - Vcap_kN / w_kNm));
    steps.push(step('crack', 'Diagonal cracks from each support', 'where V(x) = w(L/2 − x) > v cap·b·d', crackFromSupport_m, 'm', ref, CHIP.BS, note));
  }
  return {
    v_MPa, vmax_MPa, vc, vc_MPa, zone, AsvSv_min, AsvSv_req, svMax_mm, links, vCap_MPa, crackFromSupport_m,
    utilisation: v_MPa / vCap_MPa, steps, checks, ok: checks.every((c) => c.ok), ref,
  };
}

/**
 * Complete simply supported beam under a UDL, manual steps T L3702-L3896: design load, M = wL²/8, flexure (BS route,
 * OQ-01), bars, max steel 4 % (T L3563), min steel (OQ-12, needs h_mm), shear and links (OQ-13, once bars are
 * chosen), span/depth check (OQ-10, automatic once bars are chosen, or with the basicRatio/modificationFactor
 * inputs as before).
 */
function beamDesign({
  span_m, b_mm, h_mm, d_mm, Gk_kNm, Qk_kNm, fck_MPa, fcu_MPa, fy_MPa, barDia_mm, basicRatio, modificationFactor,
  linkDia_mm, linkSpacing_mm, linkLegs = 2, fyv_MPa, support = 'simple', method,
}) {
  req({ span_m, b_mm, d_mm, Gk_kNm, Qk_kNm, fy_MPa }, 'span_m', 'b_mm', 'd_mm', 'Gk_kNm', 'Qk_kNm', 'fy_MPa');
  const w_kNm = 1.4 * Gk_kNm + 1.6 * Qk_kNm;
  const M_kNm = momentSimpleUdl_kNm({ w_kNm, L_m: span_m });
  const V_kN = (w_kNm * span_m) / 2;
  const flex = flexureDesign({ M_kNm, b_mm, d_mm, fck_MPa, fcu_MPa, fy_MPa, method });
  const steps = [
    step('w', 'Ultimate load', 'w = 1.4Gk + 1.6Qk', w_kNm, 'kN/m', 'T L3714'),
    step('M', 'Maximum moment', 'M = wL²/8', M_kNm, 'kNm', 'T L3719-L3721'),
    step('V', 'Maximum shear (at supports)', 'V = wL/2', V_kN, 'kN', 'T L3181, L2240'),
    ...flex.steps,
  ];
  const checks = [...flex.checks];
  let minSteel = null;
  let As_design_mm2 = flex.As_req_mm2;
  if (h_mm && flex.As_req_mm2 !== null) {
    minSteel = minSteelArea_mm2({ b_mm, h_mm, fy_MPa });
    As_design_mm2 = Math.max(flex.As_req_mm2, minSteel);
    steps.push(step('Asmin', 'Minimum steel', fy_MPa >= 400 ? 'As min = 0.13 % b·h' : 'As min = 0.24 % b·h', minSteel, 'mm²', `${BSREF} Table 3.25`, CHIP.BS, 'The manual gives no minimum steel. BS 8110 Table 3.25 is used.'));
  }
  let bars = null;
  let shear = null;
  let deflection = null;
  if (barDia_mm && As_design_mm2 !== null) {
    bars = selectBars({ As_req_mm2: As_design_mm2, barDia_mm });
    steps.push(step('Asprov', 'Steel provided', `${bars.label}`, bars.As_prov_mm2, 'mm²', 'T L3883'));
    if (h_mm) checks.push(check('Asmax', 'As,prov ≤ 4 % b·h', bars.As_prov_mm2 <= maxSteelArea_mm2({ b_mm, h_mm }), 'T L3563'));
    const fcuS = fcu_MPa ?? fck_MPa;
    if (fcuS !== undefined) {
      shear = beamShearDesign({ V_kN, b_mm, d_mm, fcu_MPa: fcuS, As_mm2: bars.As_prov_mm2, fyv_MPa: fyv_MPa ?? fy_MPa, linkDia_mm, linkSpacing_mm, linkLegs, w_kNm, span_m });
      steps.push(...shear.steps);
      checks.push(...shear.checks);
    }
  }
  if (basicRatio !== undefined && modificationFactor !== undefined) {
    deflection = spanDepthCheck({ span_mm: span_m * 1e3, d_mm, basicRatio, modificationFactor });
  } else if (bars && flex.As_req_mm2 !== null) {
    deflection = spanDepthCheck({ span_mm: span_m * 1e3, d_mm, basicRatio, support, M_kNm, b_mm, fy_MPa, As_req_mm2: As_design_mm2, As_prov_mm2: bars.As_prov_mm2 });
  }
  if (deflection) { steps.push(...deflection.steps); checks.push(...deflection.checks); }
  return {
    w_kNm, M_kNm, V_kN, flexure: flex, minSteel_mm2: minSteel, As_design_mm2, bars, shear, deflection, steps, checks,
    ok: checks.every((c) => c.ok), ref: 'T L3702-L3896',
  };
}

/** Transverse (link) steel Ascv = Vs·S/(fy·d). T L4619-L4626 (equation in .docx). */
function linkArea({ Vs_kN, spacing_mm, fy_MPa, d_mm }) {
  return { Ascv_mm2: (Vs_kN * 1e3 * spacing_mm) / (fy_MPa * d_mm), ref: 'T L4619-L4626' };
}

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.5 - slab (T L3909-L4176)
// ---------------------------------------------------------------------------------------------------------------

/**
 * Slab type from Ly/Lx (T L3991-L4002): one-way if Ly/Lx > 2, two-way if ≤ 2 (T L3942, L3950, L3994-L3995).
 * Worked: 5 × 2 m → 2.5 one-way (T L1160); 4.5 × 4 m → 1.125 two-way (T L1177).
 * (Unit 1 and 3 say "≥ 2" for one-way, T L1159, L2689: the ratio exactly 2 is ambiguous - errata.)
 */
function slabType({ Lx_m, Ly_m }) {
  const short_m = Math.min(Lx_m, Ly_m);
  const long_m = Math.max(Lx_m, Ly_m);
  const ratio = long_m / short_m;
  return { short_m, long_m, ratio, type: ratio > 2 ? 'one-way' : 'two-way', ambiguousAtTwo: ratio === 2, ref: 'T L3991-L4002' };
}

/** Effective depth d = t − cover − φ/2. T L4003-L4010. */
const slabEffectiveDepth_mm = ({ t_mm, cover_mm, barDia_mm }) => t_mm - cover_mm - barDia_mm / 2;

/** Bar spacing S = Ab × 1000 / As (per metre width; the manual prints ×100, T L4163 - errata). T L4161-L4168. */
const barSpacingForArea_mm = ({ barDia_mm, As_mm2PerM }) => (barArea_mm2(barDia_mm) * 1000) / As_mm2PerM;

/**
 * Largest spacing in the manual's slab table that gives at least As (T L4056-L4157) and keeps the clear spacing
 * (s − φ) ≥ 75 mm (T L3543). null if none does.
 */
function slabTableSpacing({ barDia_mm, As_mm2PerM }) {
  let pick = null;
  for (const s of SLAB_TABLE_SPACINGS_mm) if (s - barDia_mm >= 75 && barsAreaPerM_mm2(barDia_mm, s) >= As_mm2PerM - 1e-9) pick = s;
  return pick === null ? null : { spacing_mm: pick, As_prov_mm2PerM: barsAreaPerM_mm2(barDia_mm, pick) };
}

/**
 * Bending moment coefficients for simply supported two-way slabs, corners not held down (BS 8110 Table 3.13; the
 * manual names two-way panels but gives no coefficients, OQ-14). msx = αsx·n·lx², msy = αsy·n·lx².
 */
const TWO_WAY_SS_COEFF = Object.freeze({
  ratios: [1.0, 1.1, 1.2, 1.3, 1.4, 1.5, 1.75, 2.0],
  alphaSx: [0.062, 0.074, 0.084, 0.093, 0.099, 0.104, 0.113, 0.118],
  alphaSy: [0.062, 0.061, 0.059, 0.055, 0.051, 0.046, 0.037, 0.029],
});

/** Two-way simply supported slab moments per metre width, linear interpolation in Table 3.13 (OQ-14). */
function twoWaySlabMoments({ Lx_m, Ly_m, n_kNm2 }) {
  const lx = Math.min(Lx_m, Ly_m);
  const ly = Math.max(Lx_m, Ly_m);
  const ratio = ly / lx;
  const { ratios, alphaSx: ax, alphaSy: ay } = TWO_WAY_SS_COEFF;
  const r = Math.min(Math.max(ratio, 1), 2);
  let k = 0;
  while (k < ratios.length - 2 && r > ratios[k + 1]) k++;
  const t = (r - ratios[k]) / (ratios[k + 1] - ratios[k]);
  const alphaSx = ax[k] + t * (ax[k + 1] - ax[k]);
  const alphaSy = ay[k] + t * (ay[k + 1] - ay[k]);
  return { lx_m: lx, ly_m: ly, ratio, alphaSx, alphaSy, msx_kNm: alphaSx * n_kNm2 * lx * lx, msy_kNm: alphaSy * n_kNm2 * lx * lx, ref: `${BSREF} Table 3.13` };
}

/**
 * Simply supported slab, 1 m strip, manual steps T L4019-L4176:
 * wu = 1.5(D + L) as printed (T L4024; OQ-04; `ultimate: 'bs'` gives 1.4gk + 1.6qk for the whole-building lab),
 * M = wL²/8 (T L4027-L4031) or, for a two-way panel (Ly_m given, Ly/Lx ≤ 2), Table 3.13 coefficients (OQ-14),
 * flexure by the BS route (OQ-01) or a given z/d, As = M/(0.87fy z) (T L4049-L4055), min steel 0.13 % b·h (OQ-12),
 * spacing S (T L4161-L4168), spacing ≤ min(3d, 300) (T L3547), deflection L/d (T L4169-L4175; OQ-10, automatic
 * when the span is known).
 */
function slabDesign({
  gk_kNm2, qk_kNm2, span_m, Ly_m, t_mm, cover_mm, barDia_mm, fck_MPa, fcu_MPa, fy_MPa, zOverD, M_kNm: Mgiven,
  basicRatio, modificationFactor, ultimate = 'manual', support = 'simple', method,
}) {
  const d_mm = slabEffectiveDepth_mm({ t_mm, cover_mm, barDia_mm });
  let wu_kNm2;
  const steps = [step('d', 'Effective depth', 'd = t − cover − φ/2', d_mm, 'mm', 'T L4005')];
  let twoWay = null;
  let M_kNm = Mgiven;
  if (Mgiven === undefined) {
    if (ultimate === 'bs') {
      wu_kNm2 = 1.4 * gk_kNm2 + 1.6 * qk_kNm2;
      steps.push(step('wu', 'Ultimate load', 'n = 1.4gk + 1.6qk', wu_kNm2, 'kN/m²', 'T L2642-L2644', CHIP.NOTE, 'The manual prints 1.5(D + L) for slabs. The whole building uses 1.4Gk + 1.6Qk throughout.'));
    } else {
      wu_kNm2 = 1.5 * (gk_kNm2 + qk_kNm2);
      steps.push(step('wu', 'Ultimate load', 'wu = 1.5 (D + L)', wu_kNm2, 'kN/m²', 'T L4024'));
    }
    const type = Ly_m !== undefined ? slabType({ Lx_m: span_m, Ly_m }) : null;
    if (type && type.type === 'two-way') {
      twoWay = twoWaySlabMoments({ Lx_m: span_m, Ly_m, n_kNm2: wu_kNm2 });
      M_kNm = twoWay.msx_kNm;
      const note = 'The manual gives no two-way moment coefficients. BS 8110 Table 3.13 (simply supported, corners not held down) is used.';
      steps.push(
        step('ratio', 'Panel ratio', 'ly / lx', twoWay.ratio, '', 'T L3991-L3999'),
        step('asx', 'Coefficient, short span', 'αsx', twoWay.alphaSx, '', `${BSREF} Table 3.13`, CHIP.BS, note),
        step('asy', 'Coefficient, long span', 'αsy', twoWay.alphaSy, '', `${BSREF} Table 3.13`, CHIP.BS, note),
        step('M', 'Moment per metre, short span', 'msx = αsx·n·lx²', M_kNm, 'kNm/m', `${BSREF} 3.5.3.3`, CHIP.BS, note),
        step('My', 'Moment per metre, long span', 'msy = αsy·n·lx²', twoWay.msy_kNm, 'kNm/m', `${BSREF} 3.5.3.3`, CHIP.BS, note),
      );
    } else {
      M_kNm = momentSimpleUdl_kNm({ w_kNm: wu_kNm2, L_m: span_m });
      steps.push(step('M', 'Moment per metre', 'M = wL²/8', M_kNm, 'kNm/m', 'T L4027'));
    }
  } else steps.push(step('M', 'Moment per metre (given)', 'M', M_kNm, 'kNm/m', 'T L5125-L5126'));
  const fcuUse = fcu_MPa ?? fck_MPa;
  const flex = flexureDesign({ M_kNm, b_mm: 1000, d_mm, fck_MPa, fcu_MPa, fy_MPa, leverArm: 'elastic', zOverD, method });
  steps.push(...flex.steps);
  const checks = [...flex.checks];
  const minSteel_mm2PerM = minSteelArea_mm2({ b_mm: 1000, h_mm: t_mm, fy_MPa });
  steps.push(step('Asmin', 'Minimum steel per metre', fy_MPa >= 400 ? 'As min = 0.13 % b·h' : 'As min = 0.24 % b·h', minSteel_mm2PerM, 'mm²/m', `${BSREF} Table 3.25`, CHIP.BS, 'The manual gives no minimum steel. BS 8110 Table 3.25 is used.'));
  const As_design_mm2PerM = flex.As_req_mm2 === null ? null : Math.max(flex.As_req_mm2, minSteel_mm2PerM);
  let spacing = null;
  if (As_design_mm2PerM !== null) {
    const S_mm = barSpacingForArea_mm({ barDia_mm, As_mm2PerM: As_design_mm2PerM });
    const Smax_mm = Math.min(3 * d_mm, 300);
    const table = slabTableSpacing({ barDia_mm, As_mm2PerM: As_design_mm2PerM });
    spacing = { S_mm, Smax_mm, table };
    steps.push(step('S', 'Bar spacing', 'S = Ab × 1000 / As', S_mm, 'mm', 'T L4163'));
    if (table) steps.push(step('Sprov', 'Spacing provided (slab table)', `Y${barDia_mm} at ${table.spacing_mm}`, table.As_prov_mm2PerM, 'mm²/m', 'T L4056-L4157'));
    const Sused_mm = table ? table.spacing_mm : S_mm;
    checks.push(check('Smax', 'Main bar spacing ≤ min(3d, 300 mm)', Math.min(S_mm, Sused_mm) <= Smax_mm, 'T L3547'));
    checks.push(check('Smin', 'Clear spacing ≥ 75 mm', Sused_mm - barDia_mm >= 75, 'T L3543'));
  }
  if (twoWay && fcuUse !== undefined) {
    const dy_mm = d_mm - barDia_mm;
    const flexY = flexureDesign({ M_kNm: twoWay.msy_kNm, b_mm: 1000, d_mm: dy_mm, fcu_MPa: fcuUse, fy_MPa });
    const AsY = Math.max(flexY.As_req_mm2, minSteel_mm2PerM);
    twoWay.long = { d_mm: dy_mm, flexure: flexY, As_design_mm2PerM: AsY, table: slabTableSpacing({ barDia_mm, As_mm2PerM: AsY }) };
  }
  let deflection = null;
  if (basicRatio !== undefined && modificationFactor !== undefined) {
    deflection = spanDepthCheck({ span_mm: span_m * 1e3, d_mm, basicRatio, modificationFactor });
  } else if (span_m !== undefined && spacing && spacing.table && flex.As_req_mm2 !== null) {
    deflection = spanDepthCheck({ span_mm: span_m * 1e3, d_mm, basicRatio, support, M_kNm, b_mm: 1000, fy_MPa, As_req_mm2: As_design_mm2PerM, As_prov_mm2: spacing.table.As_prov_mm2PerM });
  }
  if (deflection) { steps.push(...deflection.steps); checks.push(...deflection.checks); }
  return {
    d_mm, wu_kNm2, M_kNm, flexure: flex, minSteel_mm2PerM, As_design_mm2PerM, spacing, twoWay, deflection, steps, checks,
    ok: checks.every((c) => c.ok), ref: 'T L4019-L4176',
  };
}

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.7 - column (T L4343-L4655)
// ---------------------------------------------------------------------------------------------------------------

/** Effective length factors for the four end conditions of figure image127.png (T L4390-L4399). */
const EFFECTIVE_LENGTH_FACTOR = Object.freeze({ pinnedPinned: 1.0, fixedFixed: 0.5, fixedFree: 2.0, fixedPinned: 0.7 });

/**
 * BS 8110 effective length factors β (OQ-20 ruling; not in the manual). Index [top end − 1][bottom end − 1], end
 * conditions 1 (monolithic, at least as deep as the column), 2 (monolithic, shallower), 3 (nominal restraint),
 * 4 (free, unbraced top only). Braced: Table 3.19; unbraced: Table 3.20 (null = not allowed).
 */
const BETA_BRACED = Object.freeze([[0.75, 0.80, 0.90], [0.80, 0.85, 0.95], [0.90, 0.95, 1.00]]);
const BETA_UNBRACED = Object.freeze([[1.2, 1.3, 1.6], [1.3, 1.5, 1.8], [1.6, 1.8, null], [2.2, null, null]]);

/** β for a braced or unbraced column from its end conditions (1, 2, 3; unbraced top may be 4). */
function effectiveLengthFactorBS({ braced = true, endTop = 1, endBottom = 1 }) {
  const t = braced ? BETA_BRACED : BETA_UNBRACED;
  const beta = t[endTop - 1]?.[endBottom - 1];
  if (beta === undefined || beta === null) throw new TypeError(`calc: no β for ${braced ? 'braced' : 'unbraced'} ends ${endTop}/${endBottom}`);
  return { beta, braced, endTop, endBottom, ref: `${BSREF} ${braced ? 'Table 3.19' : 'Table 3.20'}` };
}

/**
 * Slenderness (T L4390-L4418): Le/D (D = least lateral dimension), r = √(I/A) (the manual prints √I / A, errata),
 * Le/r. Short if Le/D ≤ 12 and Le/r ≤ 40 (the manual's limit, used for pass/fail); BS 8110 limits 15 braced /
 * 10 unbraced are returned as `shortBS` and shown as a note. Cr = 1.25 − Le/(48b) for slender columns (T L4413-L4418).
 * Effective length: `ends` (the manual's four ideal cases, image127) or BS β (`beta`, or `braced` + `endTop` +
 * `endBottom`, Tables 3.19 / 3.20, OQ-20).
 */
function columnSlenderness({ L_mm, ends, b_mm, h_mm, beta, braced, endTop, endBottom }) {
  let factor;
  let leStep;
  if (beta !== undefined || (ends === undefined && (braced !== undefined || endTop !== undefined))) {
    const bs = beta !== undefined ? { beta, braced: braced ?? true } : effectiveLengthFactorBS({ braced, endTop, endBottom });
    factor = bs.beta;
    braced = bs.braced;
    leStep = step('Le', 'Effective length', `Le = β × L, β = ${factor}`, factor * L_mm, 'mm', `${BSREF} ${braced ? 'Table 3.19' : 'Table 3.20'}`, CHIP.BS,
      'The manual gives only the four ideal end conditions. BS 8110 β tables are used.');
  } else {
    factor = EFFECTIVE_LENGTH_FACTOR[ends];
    if (factor === undefined) throw new TypeError(`calc: unknown end condition "${ends}"`);
    leStep = step('Le', 'Effective length', `Le = ${factor} × L`, factor * L_mm, 'mm', 'T L4396 (image127)');
  }
  const Le_mm = factor * L_mm;
  const least_mm = Math.min(b_mm, h_mm);
  const sec = rectSection({ b_mm: Math.max(b_mm, h_mm), h_mm: least_mm });
  const r_mm = sec.kxx_mm; // least radius of gyration (about the axis parallel to the long side)
  const LeOverD = Le_mm / least_mm;
  const LeOverR = Le_mm / r_mm;
  const short = LeOverD <= 12 && LeOverR <= 40;
  const bsShortLimit = braced === false ? 10 : 15;
  const shortBS = LeOverD < bsShortLimit;
  const Cr = short ? 1 : 1.25 - Le_mm / (48 * least_mm);
  return {
    factor, Le_mm, least_mm, r_mm, LeOverD, LeOverR, short, bsShortLimit, shortBS, Cr,
    steps: [
      leStep,
      step('LeD', 'Slenderness ratio', 'Le / D', LeOverD, '', 'T L4392-L4394', CHIP.MANUAL, `The manual's limit is 12. BS 8110 uses 15 for braced and 10 for unbraced columns (here ${bsShortLimit}).`),
      step('r', 'Radius of gyration', 'r = √(I/A)', r_mm, 'mm', 'T L4397-L4399'),
      step('Ler', 'Le / r', 'Le / r', LeOverR, '', 'T L4409'),
      ...(short ? [] : [step('Cr', 'Reduction coefficient', 'Cr = 1.25 − Le/(48b)', Cr, '', 'T L4413-L4418')]),
    ],
    checks: [check('short', 'Short column: Le/D ≤ 12 (and Le/r ≤ 40)', short, 'T L4408-L4409', CHIP.MANUAL, `BS 8110 limit: ${bsShortLimit} (${braced === false ? 'unbraced' : 'braced'}), to confirm.`)],
    ref: 'T L4390-L4418',
  };
}

/**
 * Column detailing rules (OQ-05 ruling, BS 8110 3.12.5 and 3.12.7; not in the manual): 0.4 % Ac ≤ Asc ≤ 6 % Ac
 * (Ac taken as the gross area), at least 4 bars of 12 mm, link φ ≥ max(6 mm, ¼ largest bar), link spacing ≤ 12 ×
 * smallest bar. Too widely spaced links let the bars buckle outward between them.
 */
function columnLinkRules({ barDia_mm, Ag_mm2, linkDia_mm, linkSpacing_mm }) {
  const AscMin_mm2 = 0.004 * Ag_mm2;
  const AscMax_mm2 = 0.06 * Ag_mm2;
  const linkDiaMin_mm = Math.max(6, barDia_mm / 4);
  const linkSpacingMax_mm = 12 * barDia_mm;
  const out = { AscMin_mm2, AscMax_mm2, linkDiaMin_mm, linkSpacingMax_mm, ref: `${BSREF} 3.12.5, 3.12.7` };
  if (linkDia_mm !== undefined) out.linkDiaOk = linkDia_mm >= linkDiaMin_mm - 1e-9;
  if (linkSpacing_mm !== undefined) {
    out.linkSpacingOk = linkSpacing_mm <= linkSpacingMax_mm + 1e-9;
    out.spacingUtilisation = linkSpacing_mm / linkSpacingMax_mm;
  }
  return out;
}

/** Ultimate axial load Pu = 1.4Gk + 1.6Qk. T L4507-L4512. */
const columnUltimateLoad_kN = ({ Gk_kN, Qk_kN }) => 1.4 * Gk_kN + 1.6 * Qk_kN;

/**
 * Required gross area A = P/(fc·∅) (T L4501-L4506). ∅ (strength reduction factor) has no value in the manual: input.
 * Kept for compatibility only: the OQ-18 ruling drops this sizing (not BS); labs use columnDesign capacity instead.
 */
function columnRequiredArea({ P_kN, fc_MPa, phi }) {
  req({ phi }, 'phi');
  return { A_mm2: (P_kN * 1e3) / (fc_MPa * phi), ref: 'T L4501-L4506' };
}

/**
 * Longitudinal steel, short column (T L4513-L4521): Asc = (Pu − 0.4·fck·Ag) / (0.67·fy). Negative → concrete alone
 * carries Pu (minimum steel is not given by the manual: open question).
 */
function columnAscAxial({ Pu_kN, fck_MPa, Ag_mm2, fy_MPa }) {
  const concrete_kN = (0.4 * fck_MPa * Ag_mm2) / 1e3;
  const Asc_mm2 = (Pu_kN * 1e3 - 0.4 * fck_MPa * Ag_mm2) / (0.67 * fy_MPa);
  return { concrete_kN, Asc_mm2, ref: 'T L4513-L4521' };
}

/**
 * Column supporting an approximately symmetrical arrangement of beams (T L4484-L4486):
 * N = 0.35·fcu·Ac + 0.7·fy·Asc, with Ac = Ag − Asc (net concrete). Returns capacity for a given Asc, or the Asc
 * needed for a given N.
 */
function columnSymmetricBeams({ fcu_MPa, Ag_mm2, fy_MPa, Asc_mm2, N_kN }) {
  const out = { ref: 'T L4484-L4486' };
  if (Asc_mm2 !== undefined) {
    out.Ac_mm2 = Ag_mm2 - Asc_mm2;
    out.Ncap_kN = (0.35 * fcu_MPa * out.Ac_mm2 + 0.7 * fy_MPa * Asc_mm2) / 1e3;
  }
  if (N_kN !== undefined) out.Asc_req_mm2 = (N_kN * 1e3 - 0.35 * fcu_MPa * Ag_mm2) / (0.7 * fy_MPa - 0.35 * fcu_MPa);
  return out;
}

/**
 * Short braced column design following T L4499-L4655 (steps 1-4) with the manual's N = 0.35fcu·Ac + 0.7fy·Asc
 * (OQ-05 ruling) and bar choice; adds steel limits 0.4 % to 6 %, at least 4 bars, link rules (OQ-05) and the
 * capacity N cap with the bars provided (utilisation = Pu / N cap). Slenderness from `ends` or BS β (OQ-20).
 */
function columnDesign({
  Gk_kN, Qk_kN, b_mm, h_mm, L_mm, ends, beta, braced, endTop, endBottom, fcu_MPa, fy_MPa, barDia_mm, method = 'symmetric',
  linkDia_mm, linkSpacing_mm,
}) {
  const Pu_kN = columnUltimateLoad_kN({ Gk_kN, Qk_kN });
  const Ag_mm2 = b_mm * h_mm;
  const hasEnds = ends !== undefined || beta !== undefined || braced !== undefined || endTop !== undefined;
  const slender = L_mm !== undefined && hasEnds ? columnSlenderness({ L_mm, ends, b_mm, h_mm, beta, braced, endTop, endBottom }) : null;
  const steps = [step('Pu', 'Ultimate load', 'Pu = 1.4Gk + 1.6Qk', Pu_kN, 'kN', 'T L4509'), step('Ag', 'Gross area', 'Ag = b × h', Ag_mm2, 'mm²', 'T L4520')];
  let Asc_req_mm2;
  if (method === 'symmetric') {
    Asc_req_mm2 = columnSymmetricBeams({ fcu_MPa, Ag_mm2, fy_MPa, N_kN: Pu_kN }).Asc_req_mm2;
    steps.push(step('Asc', 'Steel required', 'N = 0.35fcu·Ac + 0.7fy·Asc → Asc', Asc_req_mm2, 'mm²', 'T L4486'));
  } else {
    Asc_req_mm2 = columnAscAxial({ Pu_kN, fck_MPa: fcu_MPa, Ag_mm2, fy_MPa }).Asc_mm2;
    steps.push(step('Asc', 'Steel required', 'Asc = (Pu − 0.4fck·Ag) / (0.67fy) (fck taken = fcu)', Asc_req_mm2, 'mm²', 'T L4516'));
  }
  const bsNote = 'The manual gives no column steel limits or link rules. BS 8110 clauses 3.12.5 and 3.12.7 are used.';
  const rules = columnLinkRules({ barDia_mm: barDia_mm ?? 12, Ag_mm2, linkDia_mm, linkSpacing_mm });
  const Asc_design_mm2 = Math.max(Asc_req_mm2, rules.AscMin_mm2);
  steps.push(step('Ascmin', 'Minimum steel', 'Asc min = 0.4 % Ac', rules.AscMin_mm2, 'mm²', rules.ref, CHIP.BS, bsNote));
  const checks = slender ? [...slender.checks] : [];
  let bars = null;
  let Ncap_kN = null;
  if (barDia_mm) {
    bars = selectBars({ As_req_mm2: Asc_design_mm2, barDia_mm });
    if (bars.n < 4) bars = { ...bars, n: 4, As_prov_mm2: 4 * bars.Abar_mm2, ok: true, label: `4Y${barDia_mm}` };
    Ncap_kN = columnSymmetricBeams({ fcu_MPa, Ag_mm2, fy_MPa, Asc_mm2: bars.As_prov_mm2 }).Ncap_kN;
    steps.push(step('Ascprov', 'Steel provided', bars.label, bars.As_prov_mm2, 'mm²', 'T L4606-L4609'));
    steps.push(step('Ncap', 'Capacity with the bars provided', 'N = 0.35fcu·Ac + 0.7fy·Asc', Ncap_kN, 'kN', 'T L4486'));
    checks.push(check('Ascprov', 'Asc,prov ≥ Asc,req', bars.As_prov_mm2 >= Asc_req_mm2, 'T L4607'));
    checks.push(check('Ascmin', 'Asc,prov ≥ 0.4 % Ac', bars.As_prov_mm2 >= rules.AscMin_mm2 - 1e-9, rules.ref, CHIP.BS, bsNote));
    checks.push(check('Ascmax', 'Asc,prov ≤ 6 % Ac', bars.As_prov_mm2 <= rules.AscMax_mm2 + 1e-9, rules.ref, CHIP.BS, bsNote));
    checks.push(check('bars', 'At least 4 bars of 12 mm or more', bars.n >= 4 && barDia_mm >= 12, rules.ref, CHIP.BS, bsNote));
  }
  if (linkDia_mm !== undefined || linkSpacing_mm !== undefined) {
    steps.push(
      step('linkDia', 'Minimum link diameter', 'φ link ≥ max(6, φ/4)', rules.linkDiaMin_mm, 'mm', rules.ref, CHIP.BS, bsNote),
      step('linkS', 'Maximum link spacing', 's ≤ 12 × smallest bar', rules.linkSpacingMax_mm, 'mm', rules.ref, CHIP.BS, bsNote),
    );
    if (linkDia_mm !== undefined) checks.push(check('linkDia', 'Link diameter ≥ max(6 mm, ¼ bar)', rules.linkDiaOk, rules.ref, CHIP.BS, bsNote));
    if (linkSpacing_mm !== undefined) checks.push(check('linkS', 'Link spacing ≤ 12 × bar (else the bars buckle between links)', rules.linkSpacingOk, rules.ref, CHIP.BS, bsNote));
  }
  if (slender) steps.unshift(...slender.steps);
  return {
    Pu_kN, Ag_mm2, slenderness: slender, Asc_req_mm2, Asc_design_mm2, bars, Ncap_kN,
    utilisation: Ncap_kN ? Pu_kN / Ncap_kN : null, links: rules, steps, checks, ok: checks.every((c) => c.ok), ref: 'T L4499-L4655',
  };
}

// ---------------------------------------------------------------------------------------------------------------
// UNIT 4.8 - soil and isolated footing (T L4676-L4928)
// ---------------------------------------------------------------------------------------------------------------

/**
 * Ultimate bearing capacity qu = c·Nc + γ·Df·Nq + 0.5·γ·B·Nγ (T L4791-L4799). The manual gives no table of Nc, Nq,
 * Nγ: they are inputs (open question).
 */
function ultimateBearingCapacity({ c_kPa, gamma_kNm3, Df_m, B_m, Nc, Nq, Ngamma }) {
  req({ Nc, Nq, Ngamma }, 'Nc', 'Nq', 'Ngamma');
  const cohesion = c_kPa * Nc;
  const surcharge = gamma_kNm3 * Df_m * Nq;
  const width = 0.5 * gamma_kNm3 * B_m * Ngamma;
  return { cohesion_kPa: cohesion, surcharge_kPa: surcharge, width_kPa: width, qu_kPa: cohesion + surcharge + width, ref: 'T L4791-L4799' };
}

/** Safe / allowable bearing = qu / factor of safety. T L4800-L4806. */
const safeBearing_kPa = ({ qu_kPa, factorOfSafety }) => qu_kPa / factorOfSafety;

/** Uniform pressure q = P/A (M = 0). T L4810-L4811, L4824-L4830. */
const uniformPressure_kPa = ({ P_kN, A_m2 }) => P_kN / A_m2;

/**
 * Pressure under an eccentric load (T L4812-L4813, L4831-L4838): q = (P/A)(1 ± 6e/B), B = footing dimension in the
 * direction of e (the manual prints "+" between the terms and calls the limit "D/6, effective depth" - errata).
 * e ≤ B/6 keeps the whole base in compression (trapezoid); e > B/6 lifts one edge.
 */
function eccentricPressure({ P_kN, B_m, L_m, e_m }) {
  const A_m2 = B_m * L_m;
  const mean_kPa = P_kN / A_m2;
  const qmax_kPa = mean_kPa * (1 + (6 * e_m) / B_m);
  const qmin_kPa = mean_kPa * (1 - (6 * e_m) / B_m);
  return { A_m2, mean_kPa, qmax_kPa, qmin_kPa, withinMiddleThird: e_m <= B_m / 6 + 1e-12, shape: e_m === 0 ? 'uniform' : e_m <= B_m / 6 ? 'trapezoidal' : 'triangular (edge lifts)', ref: 'T L4812-L4838' };
}

/** Earth pressure at depth h, p = K·γ·h (triangular distribution). T L4814-L4820. */
const earthPressure_kPa = ({ K, gamma_kNm3, h_m }) => K * gamma_kNm3 * h_m;

/**
 * Presumed allowable bearing values under vertical static load (BS 8004:1986 Table 1; NOT IN THE MANUAL, OQ-11).
 * kN/m². `value_kPa` is the value the lab uses: the middle of a closed range; for an open range ("> 600") the stated
 * bound, for "< n" about half of n. Every value carries the label 'typical value, to confirm'. 'task' is the manual's
 * own task value (Task 55 and the summative: 200 kN/m², soil not stated in the task).
 */
const SOIL_BEARING = Object.freeze([
  { id: 'denseGravel', type: 'Dense gravel, or dense sand and gravel', range: 'more than 600', min_kPa: 600, max_kPa: null, value_kPa: 600 },
  { id: 'mediumGravel', type: 'Medium dense gravel, or medium dense sand and gravel', range: '200 to 600', min_kPa: 200, max_kPa: 600, value_kPa: 400 },
  { id: 'looseGravel', type: 'Loose gravel, or loose sand and gravel', range: 'less than 200', min_kPa: 0, max_kPa: 200, value_kPa: 100 },
  { id: 'compactSand', type: 'Compact sand', range: 'more than 300', min_kPa: 300, max_kPa: null, value_kPa: 300 },
  { id: 'mediumSand', type: 'Medium dense sand', range: '100 to 300', min_kPa: 100, max_kPa: 300, value_kPa: 200 },
  { id: 'looseSand', type: 'Loose sand', range: 'less than 100', min_kPa: 0, max_kPa: 100, value_kPa: 50 },
  { id: 'hardClay', type: 'Very stiff boulder clay and hard clay', range: '300 to 600', min_kPa: 300, max_kPa: 600, value_kPa: 450 },
  { id: 'stiffClay', type: 'Stiff clay', range: '150 to 300', min_kPa: 150, max_kPa: 300, value_kPa: 225 },
  { id: 'firmClay', type: 'Firm clay', range: '75 to 150', min_kPa: 75, max_kPa: 150, value_kPa: 110 },
  { id: 'softClay', type: 'Soft clay and silt', range: 'less than 75', min_kPa: 0, max_kPa: 75, value_kPa: 40 },
  { id: 'verySoft', type: 'Very soft clay and silt', range: 'not applicable', min_kPa: null, max_kPa: null, value_kPa: null },
].map((r) => Object.freeze({ ...r, chip: CHIP.TYPICAL, ref: 'BS 8004:1986 Table 1' })));

/** One soil row by id; 'task' returns the task's own bearing value (default 200 kN/m², Task 55 / summative). */
function soilBearing(id, task_kPa = 200) {
  if (id === 'task') return { id: 'task', type: 'Not stated in the task', range: 'task value', min_kPa: task_kPa, max_kPa: task_kPa, value_kPa: task_kPa, chip: CHIP.MANUAL, ref: 'T L4951, L5129' };
  const r = SOIL_BEARING.find((x) => x.id === id);
  if (!r) throw new TypeError(`calc: unknown soil "${id}"`);
  return r;
}

/**
 * Qualitative settlement and tilt cue for the soil animation (OQ-21 ruling: no fake numbers, label "exaggerated"):
 * settlement grows with q/q allow (0 at rest, 1 at q = q allow, grows faster beyond), tilt with 6e/B.
 */
function settlementCue({ q_kPa, qa_kPa, e_m = 0, B_m = 1 }) {
  const ratio = q_kPa / qa_kPa;
  const settlement = ratio <= 1 ? 0.3 * ratio : 0.3 + 2 * (ratio - 1);
  const tilt = Math.min(1, (6 * Math.abs(e_m)) / B_m);
  return { ratio, settlement: Math.min(settlement, 3), tilt, label: 'exaggerated', fails: ratio > 1 };
}

/**
 * Square footing size (T L4841-L4856) from the SERVICE load (OQ-19): Amin = P/qa; side = √Amin; the side provided is
 * rounded up to the next 50 mm (OQ-19 ruling; the manual says "about 5 %", T L4849, which `margin` still gives);
 * qreal = P / B² ≤ qa. `B_m` overrides the provided side (the trainee's choice in the lab).
 */
function footingSize({ P_kN, qa_kPa, margin, B_m, round_m = 0.05 }) {
  const Amin_m2 = P_kN / qa_kPa;
  const sideMin_m = Math.sqrt(Amin_m2);
  let Bprov_m;
  let Bstep;
  if (B_m !== undefined) { Bprov_m = B_m; Bstep = step('B', 'Side provided', 'B (chosen)', Bprov_m, 'm', 'T L4848-L4849'); }
  else if (margin !== undefined) { Bprov_m = sideMin_m * (1 + margin); Bstep = step('B', 'Side provided', `B ≈ ${1 + margin} × √A`, Bprov_m, 'm', 'T L4848-L4849'); }
  else {
    Bprov_m = Math.round(Math.ceil(sideMin_m / round_m - 1e-9) * round_m * 1000) / 1000;
    Bstep = step('B', 'Side provided', `B = √A rounded up to the next ${round_m * 1000} mm`, Bprov_m, 'm', 'T L4848-L4849', CHIP.NOTE,
      'The manual adds about 5 % to the side. The lab rounds up to the next 50 mm.');
  }
  const qreal_kPa = P_kN / (Bprov_m * Bprov_m);
  return {
    Amin_m2, sideMin_m, B_m: Bprov_m, A_m2: Bprov_m * Bprov_m, qreal_kPa, utilisation: qreal_kPa / qa_kPa,
    steps: [
      step('Amin', 'Minimum area', 'A = P / qa', Amin_m2, 'm²', 'T L4847'),
      step('side', 'Minimum side', 'B = √A', sideMin_m, 'm', 'T L4845-L4846'),
      Bstep,
      step('qreal', 'Real soil pressure', 'q = P / (B × B)', qreal_kPa, 'kN/m²', 'T L4850-L4854'),
    ],
    checks: [check('bearing', 'q real ≤ q allowable', qreal_kPa <= qa_kPa + 1e-9, 'T L4855-L4856')],
    ref: 'T L4841-L4856',
  };
}

/**
 * Isolated square pad footing, manual procedure T L4839-L4928 with the rulings OQ-06, OQ-07, OQ-09, OQ-12, OQ-19:
 * - plan size from the SERVICE load N = Gk + Qk (+ footing self-weight, the switch `includeSelfWeight` = 10 % of
 *   Gk + Qk, summative T L5145; or `selfWeightFraction`), B rounded up to the next 50 mm (footingSize);
 * - bending and shear from the ULTIMATE column load without self-weight: Pu = 1.4Gk + 1.6Qk, qu = Pu / B²;
 * - moment at the column face over the full width: M = qu·B·a²/2, a = (B − c)/2 (the manual prints q·B²/8 with the
 *   real pressure, T L4859-L4863: returned as M_printed_kNm, chip 'manual note'); d = h − cover − 1.5φ (T L4867);
 *   flexure by the BS route with b = B; As total and per metre; min steel 0.13 % b·h;
 * - punching at the column face: u0 = 2(b + c), v = Pu/(u0·d) ≤ min(0.8√fcu, 5) (the manual prints 0.8fcu);
 * - punching at 1.5d: u = 2(b + c + 6d), V = qu × (B² − (b + 3d)(c + 3d)), v = V/(u·d) < vc (no links: (400/d)^¼ ≥ 0.67);
 * - one-way shear at d from the column face (BS 8110 3.11.3.4, not in the manual): v = qu·B·(a − d)/(B·d) < vc.
 */
function padFootingDesign({
  Gk_kN, Qk_kN, selfWeightFraction, includeSelfWeight, qa_kPa, colB_mm, colC_mm, h_mm, cover_mm, barDia_mm, fcu_MPa, fy_MPa,
  gammaM = 1.25, B_m, margin, method,
}) {
  req({ Gk_kN, Qk_kN, qa_kPa, colB_mm, colC_mm }, 'Gk_kN', 'Qk_kN', 'qa_kPa', 'colB_mm', 'colC_mm');
  const swFraction = selfWeightFraction ?? (includeSelfWeight ? 0.1 : 0);
  const selfWeight_kN = swFraction * (Gk_kN + Qk_kN);
  const GkFinal_kN = Gk_kN + selfWeight_kN;
  const N_kN = GkFinal_kN + Qk_kN;
  const size = footingSize({ P_kN: N_kN, qa_kPa, margin, B_m });
  const B = size.B_m;
  const Pu_kN = 1.4 * Gk_kN + 1.6 * Qk_kN;
  const qu_kPa = Pu_kN / (B * B);
  const qreal_kPa = size.qreal_kPa;
  const c_m = Math.min(colB_mm, colC_mm) / 1e3;
  const a_m = (B - c_m) / 2;
  const M_kNm = (qu_kPa * B * a_m * a_m) / 2;
  const M_printed_kNm = (qreal_kPa * B * B) / 8;
  const M_withUltimatePressure_kNm = (qu_kPa * B * B) / 8;
  const mNote = 'The manual prints Mmax = q B²/8 with the real soil pressure. The lab takes the moment at the column face, M = qu B a²/2, over the full width.';
  const steps = [
    step('sw', 'Footing self-weight', swFraction ? `${swFraction} × (Gk + Qk)` : 'not included', selfWeight_kN, 'kN', 'T L5145', CHIP.MANUAL,
      'The manual sizes Task 55 without it and the summative footing with 10 %.'),
    step('Gkf', 'Final dead load', 'Gk + self-weight', GkFinal_kN, 'kN', 'T L5145'),
    step('N', 'Service load for the plan size', 'N = Gk + Qk', N_kN, 'kN', 'T L5146'),
    ...size.steps,
    step('Pu', 'Ultimate column load (no self-weight)', 'Pu = 1.4Gk + 1.6Qk', Pu_kN, 'kN', 'T L5150, L3714'),
    step('qu', 'Ultimate bearing pressure', 'qu = Pu / B²', qu_kPa, 'kN/m²', 'T L5151, L4857'),
    step('a', 'Cantilever from the column face', 'a = (B − c) / 2', a_m, 'm', 'T L4859-L4863', CHIP.NOTE, mNote),
    step('M', 'Moment at the column face', 'M = qu·B·a² / 2', M_kNm, 'kNm', 'T L4859-L4863', CHIP.NOTE, mNote),
  ];
  const checks = [...size.checks];
  const out = {
    selfWeightFraction: swFraction, selfWeight_kN, GkFinal_kN, N_kN, size, B_m: B, Pu_kN, qu_kPa, qreal_kPa, a_m, M_kNm,
    M_perM_kNm: M_kNm / B, M_printed_kNm, M_withUltimatePressure_kNm, steps, checks,
  };
  if (h_mm !== undefined && cover_mm !== undefined && barDia_mm !== undefined && fcu_MPa !== undefined && fy_MPa !== undefined) {
    const d_mm = h_mm - cover_mm - 1.5 * barDia_mm;
    const Bmm = B * 1e3;
    steps.push(step('d', 'Effective depth', 'd = h − cover − φ − φ/2', d_mm, 'mm', 'T L4867-L4868'));
    const flex = flexureDesign({ M_kNm, b_mm: Bmm, d_mm, fcu_MPa, fy_MPa, method });
    steps.push(...flex.steps);
    checks.push(...flex.checks);
    const minSteel_mm2PerM = minSteelArea_mm2({ b_mm: 1000, h_mm, fy_MPa });
    const As_total_mm2 = flex.As_req_mm2;
    const As_perM_mm2 = As_total_mm2 === null ? null : As_total_mm2 / B;
    const As_design_mm2PerM = As_perM_mm2 === null ? null : Math.max(As_perM_mm2, minSteel_mm2PerM);
    steps.push(
      step('AsM', 'Steel per metre width', 'As / B', As_perM_mm2, 'mm²/m', 'T L4870-L4880'),
      step('Asmin', 'Minimum steel per metre', 'As min = 0.13 % b·h', minSteel_mm2PerM, 'mm²/m', `${BSREF} Table 3.25`, CHIP.BS, 'The manual gives no minimum steel. BS 8110 Table 3.25 is used.'),
    );
    let spacing = null;
    if (As_design_mm2PerM !== null) {
      spacing = { S_mm: barSpacingForArea_mm({ barDia_mm, As_mm2PerM: As_design_mm2PerM }), table: slabTableSpacing({ barDia_mm, As_mm2PerM: As_design_mm2PerM }) };
      steps.push(step('S', 'Bar spacing', 'S = Ab × 1000 / As', spacing.S_mm, 'mm', 'T L4163'));
      if (spacing.table) steps.push(step('Sprov', 'Spacing provided', `Y${barDia_mm} at ${spacing.table.spacing_mm}`, spacing.table.As_prov_mm2PerM, 'mm²/m', 'T L4056-L4157'));
    }
    const pNote = 'The manual prints the limit as 0.8 fcu. BS 8110 uses 0.8√fcu.';
    const u0_mm = 2 * (colB_mm + colC_mm);
    const v0_MPa = (Pu_kN * 1e3) / (u0_mm * d_mm);
    const v0Limit_MPa = Math.min(0.8 * Math.sqrt(fcu_MPa), 5);
    steps.push(
      step('u0', 'Column perimeter', 'u = 2(b + c)', u0_mm, 'mm', 'T L4889-L4891'),
      step('v0', 'Shear stress at column face', 'v = Vu / (u·d)', v0_MPa, 'N/mm²', 'T L4892-L4899'),
      step('v0max', 'Limit at the column face', 'v max = min(0.8√fcu, 5)', v0Limit_MPa, 'N/mm²', 'T L4901-L4905', CHIP.NOTE, pNote),
    );
    checks.push(check('v0', 'v < 0.8√fcu and 5 N/mm²', v0_MPa < v0Limit_MPa, 'T L4901-L4905', CHIP.NOTE, pNote));
    const a1_mm = colB_mm + 3 * d_mm;
    const c1_mm = colC_mm + 3 * d_mm;
    const u1_mm = 2 * (colB_mm + colC_mm + 6 * d_mm);
    const outside_m2 = Math.max(0, B * B - (a1_mm / 1e3) * (c1_mm / 1e3));
    const V1_kN = qu_kPa * outside_m2;
    const v1_MPa = (V1_kN * 1e3) / (u1_mm * d_mm);
    steps.push(
      step('u1', 'Perimeter at 1.5d', 'u = 2(b + c + 6d)', u1_mm, 'mm', 'T L4916-L4917'),
      step('V1', 'Shear outside the 1.5d perimeter', 'V = qu × (B² − (b + 3d)(c + 3d))', V1_kN, 'kN', 'T L4919'),
      step('v1', 'Shear stress at 1.5d', 'v = V / (u·d)', v1_MPa, 'N/mm²', 'T L4918-L4925'),
    );
    let vc = null;
    let VShear_kN = null;
    let vShear_MPa = null;
    if (spacing && spacing.table) {
      vc = concreteShearCapacity({ As_mm2: spacing.table.As_prov_mm2PerM, b_mm: 1000, d_mm, gammaM, fcu_MPa, withLinks: false });
      steps.push(vc.step);
      checks.push(check('punch', 'vc > v at 1.5d (else a punching cone forms around the column)', vc.vc_MPa > v1_MPa, 'T L4927-L4928'));
      VShear_kN = Math.max(0, qu_kPa * B * (a_m - d_mm / 1e3));
      vShear_MPa = (VShear_kN * 1e3) / (Bmm * d_mm);
      const sNote = 'The manual has no one way shear check for footings. BS 8110 clause 3.11.3.4 is used.';
      steps.push(
        step('Vs', 'Shear at d from the column face', 'V = qu·B·(a − d)', VShear_kN, 'kN', `${BSREF} 3.11.3.4`, CHIP.BS, sNote),
        step('vs', 'Shear stress at d from the face', 'v = V / (B·d)', vShear_MPa, 'N/mm²', `${BSREF} 3.11.3.4`, CHIP.BS, sNote),
      );
      checks.push(check('shear1', 'v < vc at d from the column face', vShear_MPa < vc.vc_MPa, `${BSREF} 3.11.3.4`, CHIP.BS, sNote));
    }
    Object.assign(out, {
      d_mm, flexure: flex, As_total_mm2, As_perM_mm2, minSteel_mm2PerM, As_design_mm2PerM, spacing, u0_mm, v0_MPa, v0Limit_MPa,
      u1_mm, outside_m2, V1_kN, v1_MPa, vc, VShear_kN, vShear_MPa,
      punchingUtilisation: vc ? v1_MPa / vc.vc_MPa : null,
    });
  }
  out.ok = checks.every((c) => c.ok);
  out.ref = 'T L4839-L4928';
  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Detailing values the manual does not fix (OQ-15, OQ-16)
// ---------------------------------------------------------------------------------------------------------------

/**
 * Ultimate anchorage and lap lengths as multiples of bar size (BS 8110-1:1997 Table 3.27, OQ-15; the manual has only
 * BBS rules of thumb, T L1132-L1134). Rows fcu 25, 30, 35, ≥ 40. Values agree with eq. 48 l = 0.87fy·φ/(4β√fcu)
 * with Table 3.26 β (deformed type 2: 0.5 tension, 0.63 compression; plain: 0.28, 0.35), rounded up. A web check
 * was inconclusive: to confirm. Tension lap = anchorage × 1.0, 1.4 (corner bars, cover < 2φ) or 2.0 (both);
 * compression lap = 1.25 × compression anchorage (these three rows are computed from the base rows, rounded up).
 */
const lapRows = (tension, compression) => Object.freeze({
  tension, compression,
  tension14: tension.map((v) => Math.ceil(1.4 * v - 1e-9)),
  tension20: tension.map((v) => 2 * v),
  compressionLap: compression.map((v) => Math.ceil(1.25 * v - 1e-9)),
});
const ANCHORAGE_LAP_d = Object.freeze({
  fcu: [25, 30, 35, 40],
  deformed460: lapRows([40, 37, 34, 32], [32, 29, 27, 25]),
  plain250: lapRows([39, 36, 33, 31], [32, 29, 27, 25]),
  chip: CHIP.BS,
  ref: `${BSREF} Table 3.27`,
});

/** Lap or anchorage length (mm) from Table 3.27. kind: tension | tension14 | tension20 | compression | compressionLap. */
function lapLength({ fcu_MPa, fy_MPa = 460, barDia_mm, kind = 'tension' }) {
  const row = fy_MPa >= 400 ? ANCHORAGE_LAP_d.deformed460 : ANCHORAGE_LAP_d.plain250;
  const fc = ANCHORAGE_LAP_d.fcu;
  let k = 0;
  for (let n = 0; n < fc.length; n++) if (fcu_MPa >= fc[n]) k = n;
  const multiple = row[kind][k];
  if (multiple === undefined) throw new TypeError(`calc: unknown lap kind "${kind}"`);
  return {
    multiple, L_mm: multiple * barDia_mm, fcuRow: fc[k],
    step: step('lap', 'Lap length', `${multiple} × φ (fcu ${fc[k]}${fcu_MPa < 25 ? ', below the table' : ''})`, multiple * barDia_mm, 'mm', ANCHORAGE_LAP_d.ref, CHIP.BS,
      'The manual gives only rules of thumb (40d footing, 50d column). BS 8110 Table 3.27 is used.'),
    ref: ANCHORAGE_LAP_d.ref,
  };
}

/**
 * Nominal cover per member (OQ-16 ruling): the manual's ranges (T L3379-L3405), one value per exposure
 * (mild = internal row, upper end; moderate, the default = external row, lower end; severe = external row, upper
 * end). Footings: 75 mm cast against earth, 50 mm on blinding (T L1137, summative T L5129).
 */
const COVER_DEFAULT_mm = Object.freeze({
  slab: { mild: 20, moderate: 25, severe: 30 },
  beam: { mild: 30, moderate: 30, severe: 40 },
  column: { mild: 40, moderate: 40, severe: 50 },
  footing: { earth: 75, blinding: 50 },
});

function nominalCover({ member, exposure = 'moderate', footingOn = 'blinding' }) {
  const m = COVER_DEFAULT_mm[member];
  if (!m) throw new TypeError(`calc: unknown member "${member}"`);
  const cover_mm = member === 'footing' ? m[footingOn] : m[exposure];
  if (cover_mm === undefined) throw new TypeError(`calc: unknown exposure "${exposure}"`);
  const label = member === 'footing' ? (footingOn === 'earth' ? 'cast against earth' : 'on blinding') : `${exposure} exposure`;
  return {
    cover_mm,
    step: step('cover', 'Nominal cover', `cover (${member}, ${label})`, cover_mm, 'mm', 'T L3379-L3405, L1137', CHIP.MANUAL, 'One value chosen from the manual range.'),
    ref: 'T L3379-L3405, L1137',
  };
}

